"""Write the experiment reference from machine-readable records without hand-entered scores."""
import json
from pathlib import Path
import numpy as np

def read(name):return json.loads(Path(name).read_text())
def main():
    exp=read('artifacts/experiments.json');result=read('artifacts/model-results.json');ext=read('artifacts/extended-evaluation.json');stress=read('artifacts/stress-results.json');replay=read('artifacts/replay-results.json');gen=read('artifacts/generation.json');cal=read('web/public/models/calibration.json');manifest=read('web/public/models/manifest.json')
    lines=['# Experiments and limits','','The visual encoder learns useful observation signals on the authored corpus. In the untouched final structural holdout, the corrected release model missed every clipping-positive page and produced many boundary-crossing false positives; occlusion and displacement transferred better. These results support a research review assistant with explicit human review, not automatic release approval or general production defect detection. The earlier handwritten challenge evaluated the superseded viewport-only model and remains historical evidence; its overlap failures are not the final-holdout results of the corrected model.','','A deterministic screenshot correction was made after the first held-family results had been read: Playwright requires `fullPage: true` with the fixed-width clip to retain the complete scroll height. The unchanged family splits, model architecture, optimization recipe, and seed-selection rule were rerun on corrected screenshots. The earlier numbers remain in `artifacts/viewport-only-audit/`. The original 24-family evaluation is therefore a corrected held-family rerun, not an untouched blind test. The separately authored final holdout is evaluated only once after the corrected model is frozen; its report is kept with the validation artifacts.','','## Fixed protocol','',f"The corpus has {gen['pairs']:,} real Chromium PNG pairs in 24 source families: {gen['bySplit']['train']} training, {gen['bySplit']['dev']} development, {gen['bySplit']['calibration']} calibration, and {gen['bySplit']['test']} test. The formal TypeScript candidate generator supplies all candidate rows. No ground-truth crop or DOM result is passed to the neural model. Labels are independently measured rendered observations, with unknown supervision masked. See [Data and supervision](data.md).",'',f"The release model uses seed {result['selectedSeed']}, selected by development macro PR-AUC {result['selectionDevMacroPrAuc']:.4f}. Its real source commit is `{manifest['trainingSourceSha']}`. Models have two head warmup epochs and four later encoder fine-tuning epochs. AdamW is initialized afresh each epoch, as recorded in `artifacts/training-config.json`; BatchNorm statistics remain frozen. The primary comparisons use fixed seeds 17, 29, and 43, with identical source splits and candidate labels.",'','## Candidate classification','','| Method | Held-family macro PR-AUC | Repeats |','|---|---:|---:|']
    for name,label in [('uninformed_prior','Uninformed training prior'),('pixel_difference','Pixel difference density'),('difference_statistics','Difference statistics + logistic classifier')]:lines.append(f"| {label} | {exp['baselines'][name]['test']['macroPrAuc']:.4f} | Deterministic |")
    for kind,label in [('frozen','Frozen generic visual features'),('local_only','Fine-tuned local crops'),('local_context','Fine-tuned local + context')]:
        values=np.array([r['test']['macroPrAuc'] for r in exp['models'] if r['kind']==kind]);lines.append(f'| {label} | {values.mean():.4f} ± {values.std(ddof=1):.4f} SD | 3 seeds |')
    lines+=['','![Comparison from saved metrics](figures/comparison.png)','','The visual configurations outperform the difference-statistics baseline on these families. Local-only has a slightly higher mean than local + context in the corrected run, and the difference is small relative to between-seed variation. Context did not establish a consistent gain; the release retains the prespecified local + context architecture without claiming it won the ablation. Individual seeds and all losses remain in `artifacts/experiments.json`; a favorable test seed does not determine the released weights.','','| Observation | Known candidates | Positive | Precision | Recall | F1 | PR-AUC |','|---|---:|---:|---:|---:|---:|---:|']
    for c in result['calibratedTest']['classes']:lines.append(f"| {c['label']} | {c['n']} | {c['positive']} | {c['precision']:.3f} | {c['recall']:.3f} | {c['f1']:.3f} | {c['prAuc']:.3f} |")
    b=ext['familyBootstrap'];lines += ['',f"The selected model's macro PR-AUC is {result['calibratedTest']['macroPrAuc']:.4f}; its 500-resample source-family percentile interval is [{b['macroPrAuc95Percentile'][0]:.4f}, {b['macroPrAuc95Percentile'][1]:.4f}]. Only three test source families contribute, making this interval unstable and conditional on the authored scenes.",'','![Saved development curves](figures/training-curves.png)','','## Candidate coverage and complete-system recall','']
    c=ext['localization']['test'];lines += [f"There are {c['positiveObservationRegions']} positive observation regions across {c['pagePairs']} held-family pairs. Candidate recall is {c['recallAtPoint1Coverage']:.3f} at 10% ground-truth coverage and {c['recallAtPoint5Coverage']:.3f} at 50% coverage: respectively {c['missingAtPoint1']} and {c['missingAtPoint5']} regions are missed. Mean maximum coverage is {c['meanMaxCoverage']:.3f}, while mean maximum tightness is {c['meanMaxTightness']:.3f}. The average candidate count is {c['meanCandidatesPerPage']:.3f} per pair, p95 {c['p95CandidatesPerPage']:.1f}, maximum {c['maximumCandidatesPerPage']}; {c['zeroCandidatePages']} pairs have no candidate.",'','These boxes are the union of before/after element extents, not pixel-exact defect annotations. A permissive 10% match can retain evidence without tightly localizing it. Large boxes are not awarded a high localization score merely for covering the whole page.','', '| Observation | All positive regions | Captured | Missed | Complete-system recall |','|---|---:|---:|---:|---:|']
    for r in ext['endToEndObservationRecall']:lines.append(f"| {r['label']} | {r['allPositiveObservationRegions']} | {r['captured']} | {r['missed']} | {r['recall']:.3f} |")
    lines += ['','## Review budgets','','Rank page pairs by their maximum candidate observation score. Budgets count whole page pairs, including candidate-free inputs in the denominator. These are **observation-bearing pages**, not independently confirmed defects.','','| Method | Top 10% capture | Top 25% capture | Top 50% capture |','|---|---:|---:|---:|']
    for method,curve in ext['pageReviewBudgets'].items():lines.append('| '+method+' | '+' | '.join(f"{c['capturedObservationPages']}/{c['positiveObservationPages']} ({c['captureRate']:.3f})" for c in curve)+' |')
    lines += ['','DOM contracts are checked on the separate structurally supplied challenge and integration fixtures. Their measurements are not ranked against PNG-only visual classification, and rectangle rules are not called usability or causal explanations.','','## Calibration','','Calibration uses three separate families. A class needs at least 15 known positives and 15 known negatives; other outputs stay uncalibrated. The calibration target is observation frequency on these synthetic candidates.','','| Observation | Calibration n | Positive / negative | Status | Held-family Brier | Held-family ECE |','|---|---:|---:|---|---:|---:|']
    for c,r in zip(cal['classes'],result['testReliability']):lines.append(f"| {c['label']} | {c['n']} | {c['positive']} / {c['negative']} | {c['status']} | {r['brier']:.4f} | {r['ece']:.4f} |")
    lines += ['','![Reliability bins with real sample counts](figures/reliability.png)','','Reliability is measured on the candidate population and says nothing about changes missed by candidate generation. A ten-bin ECE with few families is not a general reliability guarantee. Full bin counts are preserved in `artifacts/model-results.json`.','','## Domain and type exclusions','','These secondary probes use one fixed seed, 107. They are exploratory checks and never choose the release model. The domain probe trains and selects epochs only on light English variants 0 and 2. Dark English uses held families at variants 1 and 3. Japanese and Chinese text is separately authored and rendered on the held source structures; Chinese also changes the theme, so that result confounds script and theme.','','| Probe domain | Macro PR-AUC | Macro F1 |','|---|---:|---:|']
    for name,metric in stress['domainExclusion']['metrics'].items():lines.append(f"| {name} | {metric['macroPrAuc']:.4f} | {metric['macroF1']:.4f} |")
    symptom=stress['symptomExclusion'];c=symptom['metric']['classes'][1];lines += ['',f"The symptom-exclusion configuration removes {symptom['removedPages']} overlap-positive training page pairs before training. The excluded class has PR-AUC {c['prAuc']:.4f}, recall {c['recall']:.3f}, and F1 {c['f1']:.3f}. Its score is uncalibrated and has no positive task supervision. This failure is retained; the system does not claim reliable recognition of unseen observation types.",'','## Offline label replay','',f"The replay pool contains {replay['poolPages']} candidate-bearing training page pairs. Each strategy begins with the same 12 labeled pages per seed and uses budgets 12, 24, 48, and 96. A selected page reveals all of its existing observation labels; candidate review counts are recorded separately. Selection sees generic pretrained features and current predictions, while the oracle reveals labels only for selected pages. All strategies use the same frozen generic encoder, fixed random projection, logistic heads, seeds, and update schedule. Candidate-free pages are outside this explicitly bounded labeling pool.",'',f"Calibration-label cost is {replay['calibrationLabelCost']}; selection uses uncalibrated scores. The separate development-label cost is {replay['developmentLabelCost']} candidate-bearing page pairs. This cost is not included in the changing pool budget. The experiment does not measure human time savings.",'','| Strategy | 12 pages | 24 pages | 48 pages | 96 pages |','|---|---:|---:|---:|---:|']
    for strategy in ['random','uncertainty','uncertainty_diversity']:
        values=np.array([[c['test']['macroPrAuc'] for c in r['curve']] for r in replay['runs'] if r['strategy']==strategy]);lines.append('| '+strategy+' | '+' | '.join(f'{v:.4f}' for v in values.mean(0))+' |')
    lines += ['','![Offline replay results](figures/replay.png)','','No strategy is declared uniformly best from this small simulation. The files retain selected page IDs and revealed candidate counts at every step.','','## Runtime and numerical parity','']
    t=ext['timing'];n=ext['numericalParity'];nd=read('artifacts/numerical-batch-diagnostic.json');wg=nd['exportGraph'];lines += [f"Measured on {t['platform']} with MPS training and CPU ONNX inference: full scene generation took {gen['seconds']:.2f} s and all nine primary neural comparisons plus associated evaluation took {result['seconds']:.2f} s. The ONNX file is {t['modelBytes']:,} bytes. Its measured cold load was {t['modelLoadMilliseconds']:.2f} ms, first inference {t['coldInferenceMilliseconds']:.2f} ms, warm median {t['warmInferenceMedianMilliseconds']:.2f} ms and p95 {t['warmInferenceP95Milliseconds']:.2f} ms over {t['warmTrials']} trials at batch 1. Each input has four 96 × 96 RGB crops plus 12 geometry values.",'',f"On {n['pairs']} real candidate inputs, maximum deployment-fused PyTorch/ONNX logit error was {n['maxLogitError']:.2g}, score error {n['maxScoreError']:.2g}, with {n['thresholdDisagreements']} threshold disagreements and ranking agreement {n['candidateRankingAgrees']}. The tolerance remains 1e-4. The raw, unfused float32 PyTorch comparison separately exceeded that initial logit budget (about 1.23e-4); its calibrated score difference stayed below 7.1e-6 with zero threshold differences. This failure is retained in `artifacts/numerical-batch-diagnostic.json`. The ONNX graph contains no BatchNorm nodes, and standard PyTorch Conv/BN fusion independently agrees with its exported convolution weights within float32 rounding: maximum absolute difference {wg['maxFusedWeightDifference']:.3g}, maximum relative difference {wg['maxFusedWeightRelativeDifference']:.3g}, and maximum distance {wg['maxFusedWeightUlpDistance']} float32 ULPs (per-layer values and weight magnitudes are retained in the diagnostic). The deployed graph is not claimed to be bitwise identical to the unfused checkpoint arithmetic. This is a deployment-equivalence check, not a claim that raw float32 arithmetic is identical. Browser tests separately compare the exact decoded pixels, candidate boxes, tensors, graph output and final ranking.",'','The costs of original image generation and shared preprocessing are not hidden behind cached embeddings. `artifacts/preprocessing-timing.json` separates PNG decode, candidate generation, and tensor construction. `artifacts/end-to-end-timing.json` measures fresh Node process startup, disk transfer, and actual CPU inference from example PNGs. URL capture and UI rendering are separate operations. Peak process memory and cold/warm distinctions remain in the raw records.','','## Reproduction','','```sh','node ml/generate.mjs','python -m ml.prepare','python -m ml.train --device mps --epochs 6','python -m ml.replay --device mps','node --import tsx ml/stress-generate.mjs','python -m ml.stress --device mps','python -m ml.numerical','python -m ml.evaluate','node --import tsx ml/benchmark.mjs','python -m ml.benchmark','python -m ml.feedback --build-buffer','python -m ml.figures','python -m ml.report','```','','Use `--device cpu` where MPS is unavailable. Browser dependencies must be installed first. Raw structured training curves, seed-level metrics, calibration bins, candidate records, challenge failures, source hashes, and replay selections are public artifacts; model and data hashes are in the manifest. The next independent acceptance review is separate from these development checks.']
    holdout_path=Path('artifacts/final-holdout-results.json')
    holdout=read(str(holdout_path)) if holdout_path.exists() else {'modelSha256':None,'renderedPairs':0,'uniqueImagePairs':0,'familyCount':0,'publishedThresholds':{}}
    section=['','## Untouched final structural holdout','',f"The corrected model was evaluated once on {holdout['renderedPairs']} newly authored pairs ({holdout['uniqueImagePairs']} unique image pairs) from {holdout['familyCount']} structurally independent fixture sources. The release thresholds were frozen before predictions. This is an internal withheld evaluation, not the next independent acceptance stage. No model, threshold, or label was changed using these results.",'', '| Observation | Known pages | Positive pages | F1 | Average precision | Missed positives |','|---|---:|---:|---:|---:|---:|']
    for name,c in holdout['publishedThresholds'].items():section.append(f"| {name} | {c['knownPages']} | {c['positivePages']} | {c['f1']:.3f} | {c['averagePrecision']:.3f} | {c['fn']} |")
    section += ['', 'Clipping missed every positive page, and boundary crossing produced many false positives. Occlusion and displacement show transferable signals in these limited scenes. The sample is too small for a broad deployment claim, and the class failures are material. See `artifacts/final-holdout-results.json` for every score, per-family results, and both preregistered threshold policies.','']
    if holdout['modelSha256']!=manifest['sha256']:
        section=['','## Final structural holdout','','The archived final holdout does not correspond to these regenerated model weights. It is not reported as evaluation of this model. A new explicitly designated evaluation is required; the benchmark never silently reuses a withheld claim.','']
    where=lines.index('## Fixed protocol');lines[where:where]=section
    Path('docs/experiments.md').write_text('\n'.join(lines)+'\n')

if __name__=='__main__':main()
